)

if ($speciesToFix.Count -eq 0) {
    Write-Error "Please populate the `$speciesToFix` array with IDs from your database."
    exit
}

Write-Host "Processing $($speciesToFix.Count) species..."
$sqlOutput = @("-- Generated Taxonomy Backfill SQL")

foreach ($code in $speciesToFix) {
    $inatId = $code.Replace("inat-", "")
    Write-Host "Fetching $code ($inatId)..." -NoNewline
    
    try {
        $resp = Invoke-RestMethod -Uri "$inatApiUrl/$inatId" -Method Get
        if ($resp.results.Count -gt 0) {
            $taxon = $resp.results[0]
            $family = ($taxon.ancestors | Where-Object { $_.rank -eq "family" }).name
            $order = ($taxon.ancestors | Where-Object { $_.rank -eq "order" }).name
            
            if ($family -and $order) {
                $sqlOutput += "UPDATE [Species] SET FamilySciName = '$family', [Order] = '$order' WHERE SpeciesCode = '$code';"
                Write-Host " [OK: $family]" -ForegroundColor Green
            } else {
                Write-Host " [MISSING TAXONOMY]" -ForegroundColor Yellow
            }
        } else {
            Write-Host " [NOT FOUND]" -ForegroundColor Red
        }
    } catch {
        Write-Host " [ERROR]" -ForegroundColor Red
    }
    
    # Respect iNat rate limits (approx 1 request per second)
    Start-Sleep -Milliseconds 1100
}

$sqlOutput | Out-File -FilePath $outputFile -Encoding utf8
Write-Host "`nDone! SQL updates saved to: $outputFile" -ForegroundColor Cyan
